/** Extra state-level names beyond lib/india/states.json aliases. */
const STATE_EXTRA: [alias: string, state: string][] = [
  ["Kashmir", "IN-JK"], ["Kashmir Valley", "IN-JK"], ["Bengal", "IN-WB"], ["Delhi NCR", "IN-DL"],
];

const SINKS = [
  "Bay of Bengal", "Arabian Sea", "Indian Ocean", "West Indies", "New South Wales", "Western Australia",
  "Pakistan-occupied Kashmir", "Pakistan-administered Kashmir", "PoK", "Hyderabad House",
  "Mumbai Indians", "Chennai Super Kings", "Delhi Capitals", "Rajasthan Royals", "Gujarat Titans",
  "Kolkata Knight Riders", "Sunrisers Hyderabad", "Royal Challengers Bengaluru", "Royal Challengers Bangalore",
  "Lucknow Super Giants", "Punjab Kings", "Kerala Blasters", "Bengaluru FC", "Mumbai City FC",
  "Mohun Bagan", "East Bengal", "Hyderabad FC", "Odisha FC", "Chennaiyin",
];

type Target = { kind: "sink" } | { kind: "state"; place: Place } | { kind: "district"; places: Place[] };

const ALIASES = new Map<string, Target>();

const districtKey = (name: string, state: string) => `${state}|${name.toLowerCase()}`;
const DISTRICTS = new Map<string, Place>();
for (const p of ALL_PLACES) if (p.kind === "district") DISTRICTS.set(districtKey(p.name, p.state), p);

function addDistrictAlias(alias: string, place: Place) {
  const key = alias.toLowerCase();
  const prev = ALIASES.get(key);
  if (prev?.kind === "district") {
    if (!prev.places.includes(place)) prev.places.push(place);
  } else if (!prev) {
    ALIASES.set(key, { kind: "district", places: [place] });
  }
}

for (const s of SINKS) ALIASES.set(s.toLowerCase(), { kind: "sink" });

// States first so a district can't shadow a state name ("Chandigarh", "Puducherry", "Lakshadweep").
const STATE_POINTS = new Map(ALL_PLACES.filter((p) => p.kind === "state").map((p) => [p.state, p]));
for (const s of STATES) {
  const place = STATE_POINTS.get(s.code);
  if (!place) continue;
  for (const n of [s.name, ...s.aliases]) ALIASES.set(n.toLowerCase(), { kind: "state", place });
}
for (const [alias, code] of STATE_EXTRA) {
  const place = STATE_POINTS.get(code);
  if (place) ALIASES.set(alias.toLowerCase(), { kind: "state", place });
}
// "New Delhi" is the capital district; plain "Delhi" stays the state.
for (const p of ALL_PLACES) {
  if (p.kind !== "district") continue;
  const lower = p.name.toLowerCase();
  if (EXCLUDED.has(lower) || ALIASES.get(lower)?.kind === "state") continue;
  // "Leh (ladakh)" → also "Leh"; "Saran (chhapra)" handled via CITY_ALIASES.
  addDistrictAlias(p.name.replace(/\s*\(.*$/, ""), p);
}
for (const [alias, district, state] of CITY_ALIASES) {
  const place = DISTRICTS.get(districtKey(district, state));
  if (place) addDistrictAlias(alias, place);
}

const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const PATTERN = new RegExp(
  `(?<![\\p{L}\\p{N}])(?:${[...ALIASES.keys()]
    .sort((a, b) => b.length - a.length)
    .map(escapeRe)
    .join("|")})(?![\\p{L}\\p{N}])`,
  "giu",
);

const toMatch = (p: Place): PlaceMatch => ({
  state: p.state,
  district: p.kind === "district" ? p.name : null,
  lat: p.lat,
  lng: p.lng,
});

/** Best-guess Indian place mentioned in free text, or null. */
export function detectPlace(text: string | null | undefined): PlaceMatch | null {
  if (!text) return null;
  const states = new Map<Place, { count: number; first: number }>();
  const districtHits: { places: Place[]; index: number }[] = [];

  for (const m of text.matchAll(PATTERN)) {
    const target = ALIASES.get(m[0].toLowerCase());
    if (!target || target.kind === "sink") continue;
    if (target.kind === "state") {
      const t = states.get(target.place);
      if (t) t.count++;
      else states.set(target.place, { count: 1, first: m.index });
    } else {
      districtHits.push({ places: target.places, index: m.index });
    }
  }

  const mentionedStates = new Set([...states.keys()].map((p) => p.state));
  const districts = new Map<Place, { count: number; first: number }>();
  for (const { places, index } of districtHits) {
    let place: Place | undefined = places[0];
    if (places.length > 1) {
      const inState = places.filter((p) => mentionedStates.has(p.state));
      place = inState.length === 1 ? inState[0] : undefined;
    }
    if (!place) continue;
    const t = districts.get(place);
    if (t) t.count++;
    else districts.set(place, { count: 1, first: index });
  }

  const best = pickBest(districts) ?? pickBest(states);
  return best ? toMatch(best) : null;
}

function pickBest(tally: Map<Place, { count: number; first: number }>): Place | null {
  let best: [Place, { count: number; first: number }] | null = null;
  for (const e of tally) {
    if (!best || e[1].count > best[1].count || (e[1].count === best[1].count && e[1].first < best[1].first)) best = e;
  }
  return best ? best[0] : null;
}

/** Centroid of a state, for sources that name the state but give no coordinates. */
export function statePoint(code: string | null | undefined): PlaceMatch | null {
  const p = code ? STATE_POINTS.get(code) : undefined;
  return p ? toMatch(p) : null;
}

/** India's bounding box (with a margin for border-region quakes and cyclones offshore). */
export const INDIA_BBOX = { minLat: 5, maxLat: 38, minLng: 67, maxLng: 98.5 } as const;

export function inIndiaBox(lat: number, lng: number): boolean {
  return lat >= INDIA_BBOX.minLat && lat <= INDIA_BBOX.maxLat && lng >= INDIA_BBOX.minLng && lng <= INDIA_BBOX.maxLng;
}
